  "Zones with their own settings are NOT changed.": "Les zones avec leurs propres réglages ne sont PAS modifiées.",
  "{0} will stop using its own settings and follow the {1} Standard. Its own values will be deleted (an old copy stays in History). Zones affected: {0}.": "{0} n'utilisera plus ses propres réglages et suivra le Standard {1}. Ses propres valeurs seront supprimées (une ancienne copie reste dans l'Historique). Zones concernées : {0}.",
  "The settings of {0} will be copied into every zone of {1} and sent to their drivers. Each zone's current values are replaced. Zones affected: {2}.": "Les réglages de {0} seront copiés dans toutes les zones de {1} et envoyés à leurs chauffeurs. Les valeurs actuelles de chaque zone sont remplacées. Zones concernées : {2}.",
  "Drivers in all {0} zones that follow the Standard get this change now.": "Les chauffeurs de toutes les zones de {0} qui suivent le Standard reçoivent ce changement maintenant.",
