  "Copied to every zone and published to their drivers.": "Copié dans toutes les zones et publié à leurs chauffeurs.",
  "Each zone keeps driver app settings of its own. Copy these to every zone of the country when they should all be the same.": "Chaque zone garde ses propres réglages de l'app chauffeur. Copiez-les dans toutes les zones du pays quand elles doivent être identiques.",
