  "0 means no charge.": "0 signifie aucun frais.",
  "0 means no fee.": "0 signifie aucuns frais.",
  "0 means the pickup cannot move after accept. At most {0} m.": "0 signifie que la prise en charge ne peut pas bouger après l’acceptation. Au plus {0} m.",
  "1 day": "1 jour",
