  "3 h": "3 h",
  "3 rides 100, 5 rides 200…": "3 courses 100, 5 courses 200…",
  "3–5 working days": "3 à 5 jours ouvrés",
  "30 min": "30 min",
  "A {0} fee of {1} {2} is in the price.": "Des frais {0} de {1} {2} sont inclus dans le prix.",
  "A banned phone or card cannot open a new account.": "Un téléphone ou une carte exclu(e) ne peut pas ouvrir de nouveau compte.",
  "A button that goes straight to the driver, ride, payment or zone.": "Un bouton qui mène directement au chauffeur, à la course, au paiement ou à la zone.",
  "A card payment of {0} failed": "Un paiement par carte de {0} a échoué",
  "A concert or a match: draw the area and set the time. During the event, these dispatch rules apply in that area.": "Un concert ou un match : dessinez la zone et fixez l’horaire. Pendant l’événement, ces règles de répartition s’appliquent dans cette zone.",
  "A driver 18 min from the pickup gets Leave now {0} before pickup ({1}).": "Un chauffeur à 18 min de la prise en charge reçoit Partez maintenant {0} avant la prise en charge ({1}).",
  "A driver about to drop off a rider can get the next request, as an Exclusive offer only. Never Radar during a trip.": "Un chauffeur sur le point de déposer un passager peut recevoir la demande suivante, en offre exclusive uniquement. Jamais de Radar pendant une course.",
  "A driver can't hold two rides at the same or a close time. They see them all, but once they take one, the others that do not fit the smart gap leave their Scheduled rides.": "Un chauffeur ne peut pas avoir deux courses à la même heure ou à une heure proche. Il les voit toutes, mais dès qu’il en prend une, celles qui ne respectent pas l’écart intelligent quittent ses courses réservées.",
  "A driver cancel this close to pickup is a late cancel. The driver still pays nothing.": "Une annulation chauffeur aussi proche de la prise en charge est une annulation tardive. Le chauffeur ne paie toujours rien.",
  "A driver ending a ride close to the pickup can take it next.": "Un chauffeur qui termine une course près de la prise en charge peut la prendre ensuite.",
  "a driver group": "un groupe de chauffeurs",
  "A driver group": "Un groupe de chauffeurs",
  "A driver is on the way, waiting or driving the rider.": "Un chauffeur est en route, attend ou conduit le passager.",
  "A driver is on the way, waiting or driving.": "Un chauffeur est en route, attend ou conduit.",
  "A driver who closes the Home popup can get the ride again as an Exclusive offer, when it reaches the Exclusive step.": "Un chauffeur qui ferme la fenêtre d’accueil peut recevoir de nouveau la course en offre exclusive, quand elle atteint l’étape Exclusif.",
  "A driver who does not accept offers is set offline, so riders are not kept waiting.": "Un chauffeur qui n’accepte pas les offres est mis hors ligne, pour ne pas faire attendre les passagers.",
  "A driver's late cancel": "Annulation tardive d’un chauffeur",
  "A failed payment; rides blocked until paid": "Un paiement en échec ; courses bloquées jusqu’au règlement",
  "A female rider can ask for a female driver.": "Une passagère peut demander une conductrice.",
  "A flat price instead of km and min": "Un prix fixe au lieu des km et minutes",
  "A group or riders by name": "Un groupe ou des passagers par nom",
  "A hole needs at least 3 points inside the zone.": "Un trou nécessite au moins 3 points dans la zone.",
  "A manual surge lasts between 5 min and 12 h.": "Une majoration manuelle dure entre 5 min et 12 h.",
  "A random group of drivers in the zone, as many as you set. A new group is picked for each reservation.": "Un groupe aléatoire de chauffeurs de la zone, de la taille choisie. Un nouveau groupe est tiré pour chaque réservation.",
  "A reason is required.": "Un motif est requis.",
  "A refund waits for approval": "Un remboursement attend une approbation",
  "A refund, or a driver pay change, above this amount waits for a second admin. One limit per country, used by Payments, Trips, Riders and the server. Defaults: above {0} kr, {1} € and {2} DT.": "Un remboursement ou un changement de rémunération chauffeur au-delà de ce montant attend un second admin. Une limite par pays, utilisée par Paiements, Courses, Passagers et le serveur. Par défaut : au-delà de {0} kr, {1} € et {2} DT.",
  "A request for this is already waiting for a second admin.": "Une demande pour cela attend déjà un second admin.",
  "A ride booked for later. Its free wait is the included waiting of the reservation policy.": "Une course réservée pour plus tard. Son attente gratuite est l’attente incluse de la politique de réservation.",
  "A ride counts when": "Une course compte quand",
  "A ride Movera gives to a driver always says “Assigned by Movera”.": "Une course que Movera donne à un chauffeur indique toujours « Attribuée par Movera ».",
  "A ride payment failed": "Un paiement de course a échoué",
  "A ride starts in {0} and ends in another zone. What happens?": "Une course commence en {0} et se termine dans une autre zone. Que se passe-t-il ?",
  "A ride with no driver this close to pickup needs attention.": "Une course sans chauffeur aussi proche de la prise en charge demande de l’attention.",
  "A rider and a driver can be in different zones. Drivers are matched across zone borders.": "Un passager et un chauffeur peuvent être dans des zones différentes. Les chauffeurs sont attribués au-delà des limites de zone.",
  "A rider and a driver who reported each other never meet again.": "Un passager et un chauffeur qui se sont signalés mutuellement ne se rencontrent plus jamais.",
  "A rider waits too long": "Un passager attend trop longtemps",
  "A rider with an unpaid ride above the amount cannot book until it is paid.": "Un passager avec une course impayée au-delà du montant ne peut pas réserver tant qu’elle n’est pas payée.",
  "A run above this total waits until another admin approves it.": "Un lot au-delà de ce total attend l’approbation d’un autre admin.",
  "A second admin must approve. You asked for this change.": "Un second admin doit approuver. Vous avez demandé cette modification.",
  "A second admin must decide.": "Un second admin doit décider.",
  "A second agent must approve.": "Un second agent doit approuver.",
  "A second agent must publish.": "Un second agent doit publier.",
  "A second authorised agent must decide this action.": "Un second agent autorisé doit décider de cette action.",
  "A second driver is ready if the first cancels.": "Un second chauffeur est prêt si le premier annule.",
  "A stopped promotion cannot be changed.": "Une promotion arrêtée ne peut pas être modifiée.",
  "A system error is shown as Critical, a rider's card as Important.": "Une erreur système est Critique, la carte d’un passager Importante.",
  "A time rule wins over the choice above while it runs.": "Une règle horaire l’emporte sur le choix ci-dessus pendant qu’elle s’applique.",
  "A trip counts when its drop-off is this close to the driver's road route to the destination and the trip brings the driver closer.": "Une course compte quand sa dépose est aussi proche de l’itinéraire routier du chauffeur vers sa destination et qu’elle le rapproche.",
  "A trip the driver hid in the Live list can come back if nobody took it and it is still in Radar. It never counts against the driver.": "Une course que le chauffeur a masquée dans la liste En direct peut revenir si personne ne l’a prise et qu’elle est toujours en Radar. Elle ne compte jamais contre le chauffeur.",
  "A very hard stop or impact. The card opens at once, with Call 112 on top.": "Un arrêt très brusque ou un choc. La fiche s’ouvre immédiatement, avec Appeler le 112 en haut.",
  "A5 size. Print it, put it in cars, at the airport or share the picture on social media.": "Format A5. Imprimez-le, posez-le dans les voitures, à l’aéroport, ou partagez l’image sur les réseaux sociaux.",
