  "drivers": "chauffeurs",
  "Drivers": "Chauffeurs",
  "Drivers are paid for the drive to the pickup, from their live location when the offer shows. It is worked out again each time the offer shows. The rider's price never changes.": "Les chauffeurs sont payés pour le trajet jusqu’à la prise en charge, depuis leur position quand l’offre s’affiche. C’est recalculé à chaque affichage de l’offre. Le prix du passager ne change jamais.",
  "Drivers can ask for rides only towards their destination.": "Les chauffeurs peuvent demander des courses uniquement vers leur destination.",
  "Drivers can ask for rides towards home": "Les chauffeurs peuvent demander des courses vers leur domicile",
  "Drivers can leave the zone": "Les chauffeurs peuvent quitter la zone",
