  "Drivers for the bonus": "Chauffeurs pour le bonus",
  "Drivers get the highest step they reach, not all of them added up.": "Les chauffeurs reçoivent le palier le plus haut atteint, pas la somme de tous.",
  "Drivers I pick": "Chauffeurs que je choisis",
  "Drivers in {0} set a destination and get trips that bring them closer. Each part has its own switch; a part that is off has no limit.": "Les chauffeurs en {0} fixent une destination et reçoivent des courses qui les en rapprochent. Chaque partie a son propre interrupteur ; une partie désactivée n’a pas de limite.",
