  "Every {0} min smart surge compares {1} with {2} (online and not on a trip). Many drivers and few requests means no surge. It starts only when a level holds for {3} min, goes down one step at a time, waits {4} min between changes, and stops by itself when the level stays low for {5} min.": "Toutes les {0} min, la majoration intelligente compare {1} avec {2} (en ligne et pas en course). Beaucoup de chauffeurs et peu de demandes : pas de majoration. Elle démarre seulement quand un niveau tient {3} min, descend d’un palier à la fois, attend {4} min entre deux changements, et s’arrête d’elle-même quand le niveau reste bas pendant {5} min.",
