  "Welcome to Movera": "Bienvenue chez Movera",
  "What a fleet owner gets from their drivers' rides, after commission.": "Ce qu’un propriétaire de flotte reçoit des courses de ses chauffeurs, après commission.",
  "What a new driver must upload in this country. The driving licence is always needed.": "Ce qu’un nouveau chauffeur doit envoyer dans ce pays. Le permis de conduire est toujours requis.",
  "What an admin picks when cancelling a trip from Trips. The codes are fixed by the shared contract.": "Ce qu’un admin choisit en annulant une course depuis Courses. Les codes sont fixés par le contrat partagé.",
  "What changed": "Ce qui a changé",
  "What drivers and riders choose from when they cancel. Mark a reason “Doesn't count” and it never hurts the cancel rate or the late-cancel rule, for example a rider no-show, safety or a car problem. An empty language shows the English text.": "Ce que chauffeurs et passagers choisissent quand ils annulent. Marquez un motif « Ne compte pas » et il ne pénalise jamais le taux d’annulation ni la règle d’annulation tardive, par exemple une absence du passager, la sécurité ou un problème de véhicule. Une langue vide affiche le texte anglais.",
  "What happened, what you did": "Ce qui s’est passé, ce que vous avez fait",
  "What happens second by second": "Ce qui se passe seconde par seconde",
  "What is {0}?": "Qu’est-ce que {0} ?",
  "What is it about?": "De quoi s’agit-il ?",
  "What is needed?": "Qu’est-ce qui est nécessaire ?",
  "What is the case about": "Sur quoi porte le dossier",
