  "What Movera keeps from the trip price": "Ce que Movera garde du prix de la course",
  "What riders paid on average for completed trips, before tips.": "Ce que les passagers ont payé en moyenne pour les courses terminées, avant pourboires.",
  "What the driver sees before accepting, on the Radar card, the Exclusive card and the reservation popup. Switch each detail on or off.": "Ce que le chauffeur voit avant d’accepter, sur la fiche Radar, la fiche Exclusif et la fenêtre de réservation. Activez ou désactivez chaque détail.",
  "What the driver sees, {0}": "Ce que voit le chauffeur, {0}",
  "What the driver's offer card shows": "Ce que montre la fiche de l’offre du chauffeur",
  "What the rider app asks when the rider cancels.": "Ce que l’appli passager demande quand le passager annule.",
  "What the rider can pay with, and the language each app starts in. The same four methods are offered in every country; untick one to turn it off there. The wallet stays: one balance per currency, used first (Features › Wallet).": "Ce avec quoi le passager peut payer, et la langue de démarrage de chaque appli. Les quatre mêmes moyens sont proposés dans chaque pays ; décochez-en un pour le désactiver là-bas. Le portefeuille reste : un solde par devise, utilisé en premier (Fonctions › Portefeuille).",
  "What the rider sees while waiting": "Ce que voit le passager pendant l’attente",
  "What to copy": "Quoi copier",
