  "When the driver accepted": "Quand le chauffeur a accepté",
  "When the driver and rider apps ask \"Is everything OK?\". Same for every zone; the switches per zone are in Dispatch → Rules → Safety.": "Quand les applis chauffeur et passager demandent « Tout va bien ? ». Identique pour chaque zone ; les interrupteurs par zone sont dans Répartition → Règles → Sécurité.",
  "When the driver can get the next trip while driving a rider. Each limit has its own switch; with both off, offers can come on the whole last leg.": "Quand le chauffeur peut recevoir la course suivante en conduisant un passager. Chaque limite a son interrupteur ; si les deux sont désactivées, les offres peuvent arriver sur toute la dernière étape.",
