  "Winning order: global → market → zone → category → app → platform → app version → cohort.": "Ordre de priorité : global → marché → zone → catégorie → appli → plateforme → version d’appli → cohorte.",
  "With Movera 3+ months and ride often": "Avec Movera depuis plus de 3 mois et voyagent souvent",
  "With promotion": "Avec promotion",
  "With ranges, the whole pickup is paid at the rate of the range its km falls into (exactly 10 km is in 0–10). Ranges go up with no gaps; only the last can be \"and above\", and longer pickups than a closed last range use the last range.": "Avec des tranches, toute l’approche est payée au tarif de la tranche où tombent ses km (exactement 10 km est dans 0–10). Les tranches montent sans trou ; seule la dernière peut être « et plus », et les approches plus longues qu’une dernière tranche fermée utilisent la dernière tranche.",
