  "You can earn up to {0}": "Vous pouvez gagner jusqu’à {0}",
  "You can look at the settings. Only Super admin and Operations can change them. Your own quiet hours are at the bottom.": "Vous pouvez consulter les réglages. Seuls Super admin et Opérations peuvent les modifier. Vos propres heures calmes sont en bas.",
