  "Send again by itself": "Renvoyer automatiquement",
  "Small offer cards while the driver is on the map screen. Independent of the full-screen list.": "Petites cartes d’offre quand le chauffeur est sur l’écran carte. Indépendantes de la liste plein écran.",
  "The other dispatch rules: best driver, rider waiting, rides and stops, drivers, safety, alerts": "Les autres règles de dispatch : meilleur chauffeur, attente du passager, courses et arrêts, chauffeurs, sécurité, alertes",
  "Time on the radar{0}": "Temps sur le radar{0}",
  "Two radar screens, each with its own limit: the full-screen list and the offer cards over the map. The driver app detects whether the car is moving.": "Deux écrans radar, chacun avec sa propre limite : la liste plein écran et les cartes d’offre sur la carte. L’app chauffeur détecte si la voiture roule.",
  "When the driver opens the radar screen: a list of the rides on the radar.": "Quand le chauffeur ouvre l’écran radar : une liste des courses sur le radar.",
  "While the car is moving the driver cannot open the list. It opens again as soon as the car stops.": "Quand la voiture roule, le chauffeur ne peut pas ouvrir la liste. Elle s’ouvre à nouveau dès que la voiture s’arrête.",
  "rule {0}: {1} s, up to {2} drivers": "règle {0} : {1} s, jusqu’à {2} chauffeurs",
  "sends again by itself": "renvoie automatiquement",
  "sends once": "envoie une fois",
  "{0} Back to radar zones": "{0} Retour aux zones radar",
  "{0} Dispatch rules": "{0} Règles de dispatch",
  "{0} Draw it on the map like a zone: shape, rectangle, circle or free hand. It belongs to {1}. Radar zones may overlap; a radar sent to this one goes to the free drivers inside it at that moment.": "{0} Dessinez-la sur la carte comme une zone : forme, rectangle, cercle ou main levée. Elle appartient à {1}. Les zones radar peuvent se chevaucher ; un radar envoyé vers celle-ci va aux chauffeurs libres qui s’y trouvent à ce moment.",
  "{0} Full-screen radar list": "{0} Liste radar plein écran",
  "{0} How Radar, Exclusive and reservation offers work is set in {1}.": "{0} Le fonctionnement des offres Radar, Exclusif et réservations se règle dans {1}.",
  "{0} New radar zone": "{0} Nouvelle zone radar",
  "{0} Offer cards on the map": "{0} Cartes d’offre sur la carte",
  "{0} Radar zone rules · all of {1}": "{0} Règles des zones radar · toute la {1}",
  "{0} Radar zones in {1}": "{0} Zones radar dans {1}",
  "{0} Radar · Exclusive · Reservations": "{0} Radar · Exclusif · Réservations",
  "{0} The app waits about 10 seconds before switching between stopped and driving, so a traffic light does not flip the cards. Cards never pop over the navigation while driving.": "{0} L’app attend environ 10 secondes avant de basculer entre arrêt et conduite, pour qu’un feu rouge ne fasse pas sauter les cartes. Les cartes n’apparaissent jamais par-dessus la navigation en roulant.",
  "{0} The best driver, drivers finishing a ride nearby and favourite drivers are in {1}. What the offer card shows is in {2}.": "{0} Le meilleur chauffeur, les chauffeurs qui terminent une course à proximité et les chauffeurs favoris sont dans {1}. Ce que la carte d’offre affiche est dans {2}.",
  "{0} Wider area: the search distance steps in {1}. Which mode runs, by time or how busy, is in {2}.": "{0} Zone élargie : les paliers de distance de recherche dans {1}. Quel mode tourne, selon l’heure ou l’affluence, est dans {2}.",
  "{0} km² · {1}": "{0} km² · {1}",
  "{0} km² · {1} free driver{2} inside right now": "{0} km² · {1} chauffeur{2} libre{2} à l’intérieur en ce moment",
  "{0} moved": "{0} déplacé",
  "{0} moved to Radar · Exclusive · Reservations": "{0} : déplacé vers Radar · Exclusif · Réservations",
  "{0} s · up to {1} drivers · {2}": "{0} s · jusqu’à {1} chauffeurs · {2}",
