  "Events: a concert or a match": "Événements : un concert ou un match",
  "No rule yet: every radar zone uses its zone's normal radar time and drivers.": "Pas encore de règle : chaque zone radar utilise le temps radar et les chauffeurs normaux de sa zone.",
  "the zone's normal radar time and drivers": "le temps radar et les chauffeurs normaux de la zone",
  "Radar · Exclusive · Reservations › Radar": "Radar · Exclusif · Réservations › Radar",
  "Radar · Exclusive · Reservations › Exclusive": "Radar · Exclusif · Réservations › Exclusif",
  "Radar · Exclusive · Reservations › Reservations": "Radar · Exclusif · Réservations › Réservations",
  "Full-screen radar list locked while driving": "Liste radar plein écran verrouillée en roulant",
