  // Handle panel
  " · rule “{0}”": " · règle « {0} »",
  "Draw one in Radar · Exclusive · Reservations": "Dessinez-en une dans Radar · Exclusif · Réservations",
  "Driver group": "Groupe de chauffeurs",
  "Drivers for the radar": "Chauffeurs pour le radar",
  "Ends the search. The rider is told that no driver was found.": "Arrête la recherche. Le passager est informé qu’aucun chauffeur n’a été trouvé.",
  "Exclusive offer to the nearest free driver who can drive {0}: {1}, {2} km": "Offre exclusive au chauffeur libre le plus proche pouvant conduire {0} : {1}, {2} km",
  "Exclusive offer to {0}": "Offre exclusive à {0}",
  "Exclusive to nearest": "Exclusif au plus proche",
  "Handle opens the same panel as on the Dashboard: Exclusive (one offer to one nearby driver) and Radar (a radar zone, whole zones, a driver group or drivers you tick, up to 10), again and again until one accepts. Exclusive to nearest offers the ride to the nearest free driver now.": "Gérer ouvre le même panneau que sur le tableau de bord : Exclusif (une offre à un chauffeur proche) et Radar (une zone radar, des zones entières, un groupe de chauffeurs ou des chauffeurs cochés, jusqu’à 10), encore et encore jusqu’à ce qu’un chauffeur accepte. Exclusif au plus proche propose la course au chauffeur libre le plus proche maintenant.",
  "Max drivers who can see it": "Nombre max. de chauffeurs qui la voient",
  "Nearby driver": "Chauffeur à proximité",
  "Nearest free drivers": "Chauffeurs libres les plus proches",
  "Next to it": "Juste à côté",
  "No free driver in the list above.": "Aucun chauffeur libre dans la liste ci-dessus.",
  "No free driver inside right now. The radar still goes out and reaches drivers who come in.": "Aucun chauffeur libre à l’intérieur pour le moment. Le radar part quand même et atteint les chauffeurs qui entrent.",
  "No radar zone here yet. {0}": "Pas encore de zone radar ici. {0}",
  "Or tick drivers yourself": "Ou cochez les chauffeurs vous-même",
  "See the active drivers near the pickup: send an exclusive offer or a radar": "Voir les chauffeurs actifs près du départ : envoyer une offre exclusive ou un radar",
  "Send exclusive offer": "Envoyer l’offre exclusive",
  "Send the ride to a radar zone, to whole zones or to a driver group; or tick the drivers yourself. The first to accept takes it.": "Envoyez la course à une zone radar, à des zones entières ou à un groupe de chauffeurs ; ou cochez les chauffeurs vous-même. Le premier qui accepte la prend.",
  "The rider only sees “Searching” until a driver accepts. Exclusive: one offer to one driver. Radar: several drivers at once, up to {0}. Repeat until someone accepts.": "Le passager voit seulement « Recherche » jusqu’à ce qu’un chauffeur accepte. Exclusif : une offre à un chauffeur. Radar : plusieurs chauffeurs à la fois, jusqu’à {0}. Répétez jusqu’à ce que quelqu’un accepte.",
  "This zone + zones around": "Cette zone + zones autour",
  "This zone only": "Cette zone seulement",
  "Which radar zones": "Quelles zones radar",
  "the radar for {0}": "le radar de {0}",
  "{0} Active drivers near the pickup. Click a driver’s name to send the exclusive offer; the driver has {1} s to accept.": "{0} Chauffeurs actifs près du départ. Cliquez sur le nom d’un chauffeur pour envoyer l’offre exclusive ; il a {1} s pour accepter.",
  "{0} Cancel request": "{0} Annuler la demande",
  "{0} Exclusive to nearest offers the ride to the nearest free driver who is allowed to drive the requested category. Handle opens Exclusive and Radar, the same panel as in Dispatch.": "{0} Exclusif au plus proche propose la course au chauffeur libre le plus proche autorisé à conduire la catégorie demandée. Gérer ouvre Exclusif et Radar, le même panneau que dans Dispatch.",
  "{0} Exclusive · one driver at a time": "{0} Exclusif · un chauffeur à la fois",
  "{0} Handle": "{0} Gérer",
  "{0} Radar · several drivers at once": "{0} Radar · plusieurs chauffeurs à la fois",
  "{0} Send again": "{0} Renvoyer",
  "{0} Send radar": "{0} Envoyer le radar",
  "{0} Timer {1} s{2}": "{0} Minuteur {1} s{2}",
  "{0} free driver(s) inside right now get the radar": "{0} chauffeur(s) libre(s) à l’intérieur reçoivent le radar maintenant",
  "{0} free driver{1} inside": "{0} chauffeur{1} libre{1} à l’intérieur",
  " · the zone's radar": " · le radar de la zone",
  "Send {0}'s ride to the radar for {1}: up to {2} drivers see it, {3} right now.": "Envoyer la course de {0} au radar de {1} : jusqu’à {2} chauffeurs la voient, {3} pour le moment.",
  "Pick at least one zone.": "Choisissez au moins une zone.",
