  "Accepted by {0}": "Acceptée par {0}",
  "Add {0} for the driver on {1} ({2}). Movera pays it; the rider’s price does not change.": "Ajouter {0} pour le chauffeur sur {1} ({2}). Movera le paie ; le prix du passager ne change pas.",
