  "Type the amount and choose where it applies: the next Exclusive or Radar send carries it, and every send button shows what the driver will see. Movera pays it from its commission; the rider never pays it.": "Saisissez le montant et choisissez où il s’applique : le prochain envoi Exclusif ou Radar l’emporte, et chaque bouton d’envoi montre ce que verra le chauffeur. Movera le paie sur sa commission ; le passager ne le paie jamais.",
