  "Texts in Swedish, French and English for the apps. Publish sends them to the zones chosen at the top; one admin is enough. History and rollback come from the server.": "Textes en suédois, français et anglais pour les applis. Publier les envoie aux zones choisies en haut ; un seul admin suffit. L'historique et le retour arrière viennent du serveur.",
  "Content studio in Swedish, French and English. A second agent must publish. Originals and every publication remain in history. Simulation only.": "Studio de contenu en suédois, français et anglais. Un second agent doit publier. Les originaux et chaque publication restent dans l'historique. Simulation uniquement.",
