  "No driver of that group or area is free right now.": "Aucun chauffeur de ce groupe ou de cette zone n’est libre pour l’instant.",
  "That rule is not for this radar zone. Pick another rule.": "Cette règle ne vaut pas pour cette zone radar. Choisissez une autre règle.",
  "A radar zone rule still lists this radar zone. Change the rule first.": "Une règle de zones radar inclut encore cette zone radar. Modifiez d’abord la règle.",
  "No radar is sending again for this ride.": "Aucun radar n’est renvoyé pour cette course.",
  "This group is used by a booked ride. It cannot be deleted now.": "Ce groupe est utilisé par une course réservée. Il ne peut pas être supprimé maintenant.",
  "A radar zone of another country is in the rule.": "Une zone radar d’un autre pays figure dans la règle.",
  "The outline is not valid. Draw it again.": "Le contour n’est pas valide. Dessinez-le à nouveau.",
  "This country is outside your zones.": "Ce pays est en dehors de vos zones.",
